// Generic add/update/manage list — used for Saved Forecasts (Vaccine Forecasting)
// and Saved Session Plans (Session Planning), per client feedback item 7.
const RecordManager = ({ records, onAdd, onUpdate, onDelete, placeholderTitle, placeholderNotes }) => {
  const [editingId, setEditingId] = useState(null);
  const [title, setTitle] = useState("");
  const [notes, setNotes] = useState("");
  const startNew = () => { setEditingId("new"); setTitle(""); setNotes(""); };
  const startEdit = (r) => { setEditingId(r.id); setTitle(r.title); setNotes(r.notes); };
  const cancel = () => { setEditingId(null); setTitle(""); setNotes(""); };
  const save = () => {
    if (!title.trim()) return;
    if (editingId === "new") onAdd({ id: `rec-${Date.now()}`, title: title.trim(), notes: notes.trim(), date: new Date().toLocaleDateString() });
    else onUpdate(editingId, { title: title.trim(), notes: notes.trim() });
    cancel();
  };
  return (
    <div style={{ display: "grid", gap: 10 }}>
      {editingId ? (
        <Card>
          <div style={{ display: "grid", gap: 8 }}>
            <Input label="Title" placeholder={placeholderTitle} value={title} onChange={e => setTitle(e.target.value)} />
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <label style={{ fontSize: 13, color: "var(--text)", fontWeight: 700 }}>Notes</label>
              <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder={placeholderNotes} rows={3}
                style={{ padding: 12, borderRadius: 10, border: "1px solid var(--border)", fontSize: 14, fontFamily: "inherit", resize: "vertical" }} />
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={save} style={{ flex: 1, padding: 10, borderRadius: 10, background: TILE_BLUE, color: "#fff", border: "none", fontWeight: 700 }}>{editingId === "new" ? "Add" : "Save changes"}</button>
              <button onClick={cancel} style={{ flex: 1, padding: 10, borderRadius: 10, background: "var(--surface-alt)", border: "none" }}>Cancel</button>
            </div>
          </div>
        </Card>
      ) : (
        <button onClick={startNew} style={{ padding: 12, borderRadius: 10, background: "#EAF1F8", border: `1px dashed ${TILE_BLUE}`, color: TILE_BLUE, fontWeight: 700, cursor: "pointer" }}>+ Add new</button>
      )}
      {records.length === 0 && !editingId && <div style={{ color: "var(--text-subtle)", fontSize: 13, textAlign: "center", padding: 12 }}>Nothing saved yet.</div>}
      {records.map(r => (
        <Card key={r.id}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 }}>
            <div>
              <div style={{ fontWeight: 800 }}>{r.title}</div>
              {r.notes && <div style={{ color: "var(--text-muted)", marginTop: 4, fontSize: 13 }}>{r.notes}</div>}
              <div style={{ color: "var(--text-subtle)", fontSize: 11, marginTop: 4 }}>{r.date}</div>
            </div>
            <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
              <button onClick={() => startEdit(r)} style={{ padding: "6px 8px", borderRadius: 8, background: "var(--surface-alt)", border: "none", fontSize: 11, fontWeight: 700 }}>Edit</button>
              <button onClick={() => onDelete(r.id)} style={{ padding: "6px 8px", borderRadius: 8, background: "#FEE2E2", color: "#ef4444", border: "none", fontSize: 11, fontWeight: 700 }}>Delete</button>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );
};

/* ===========================
   FORECASTING CALCULATOR
   Per IIP Ch 2.2 / SRS FR-C2, KB-F01..F05
   =========================== */
function ForecastingCalculator({ onComplete, completed }) {
  const [method, setMethod] = useState("target_population");
  const [reconstituted, setReconstituted] = useState(false); // BCG/Measles -> mixing syringe applies
  const [inputs, setInputs] = useState({
    targets: "", coverage: "", dosesPerPerson: "",
    begin: "", received: "", end: "", wasted: "",
    posts: "", weeks: "", sessionsPerWeek: "", vialsPerSession: "",
    wastageRatePct: "", dosesPerVial: ""
  });
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");

  const change = (k, v) => setInputs(i => ({ ...i, [k]: v }));

  const calculate = () => {
    setError("");
    const wastageRatePct = parseFloat(inputs.wastageRatePct) || 5;
    if (wastageRatePct >= 100 || wastageRatePct < 0) return setError("Wastage rate must be between 0 and 99%.");
    const wastageFactor = 100 / (100 - wastageRatePct); // IIP Ch 2.4.1
    const dosesPerVial = parseFloat(inputs.dosesPerVial) || 1;

    let annualDoses = 0;
    if (method === "target_population") {
      const targets = Number(inputs.targets || 0);
      const coverage = Number(inputs.coverage || 100) / 100;
      const doses = Number(inputs.dosesPerPerson || 1);
      if (!targets || targets <= 0) return setError("Enter a valid target population (e.g. Live Births / Surviving Infants).");
      // Annual Need = Target population * Coverage * doses per individual * Wastage Factor  (IIP Ch 2.2.1)
      annualDoses = targets * coverage * doses * wastageFactor;
    } else if (method === "consumption") {
      const begin = Number(inputs.begin || 0), received = Number(inputs.received || 0), end = Number(inputs.end || 0), wasted = Number(inputs.wasted || 0);
      // Vaccine need = (Beginning Balance + Received) - (Ending balance + Wasted unopened dose) (IIP Ch 2.2.1 Table 2.1)
      annualDoses = (begin + received) - (end + wasted);
      if (annualDoses <= 0) return setError("Consumption inputs give zero or negative need; check values.");
    } else if (method === "immunization_session") {
      const posts = Number(inputs.posts || 0), weeks = Number(inputs.weeks || 52), sessionsPerWeek = Number(inputs.sessionsPerWeek || 1), vialsPerSession = Number(inputs.vialsPerSession || 0);
      if (!posts || !weeks || !sessionsPerWeek || !vialsPerSession) return setError("Fill all session planning fields.");
      // Annual need = posts * weeks * sessions/week * avg vials/session * doses/vial (IIP Ch 2.2.1 Table 2.1)
      annualDoses = posts * weeks * sessionsPerWeek * vialsPerSession * dosesPerVial;
    }

    const annual = Math.ceil(annualDoses);
    const monthly = Math.ceil(annual / 12);

    // AD Syringe = Targets*Coverage*doses*WastageFactor -> equal to the dose need (1 AD syringe per dose) (IIP Ch 2.2.1)
    const adSyringeAnnual = annual;
    const adSyringeMonthly = monthly;

    // Number of Vials = total doses / doses per vial (IIP Ch 2.2.1)
    const vialsAnnual = Math.ceil(annual / dosesPerVial);

    // Mixing Syringe = Number of Vials * Wastage Factor — ONLY for reconstituted vaccines (BCG & Measles) (IIP Ch 2.2.1 note)
    const mixingSyringeAnnual = reconstituted ? Math.ceil(vialsAnnual * wastageFactor) : 0;
    const mixingSyringeMonthly = Math.ceil(mixingSyringeAnnual / 12);

    // Safety box = (Total AD Syringe + Total Mixing Syringe) * Wastage Factor / 100 (IIP Ch 2.2.1)
    const safetyBoxAnnual = Math.ceil(((adSyringeAnnual + mixingSyringeAnnual) * wastageFactor) / 100);
    const safetyBoxMonthly = Math.ceil(safetyBoxAnnual / 12);

    // 25% buffer stock — separate stock-management concept, informational (IIP Ch 2.2 / 2.3.1)
    const bufferStockAnnual = Math.ceil(annual * 0.25);

    setResult({
      annual, monthly, wastageRatePct, wastageFactor: Number(wastageFactor.toFixed(3)),
      adSyringeAnnual, adSyringeMonthly,
      vialsAnnual,
      mixingSyringeAnnual, mixingSyringeMonthly,
      safetyBoxAnnual, safetyBoxMonthly,
      bufferStockAnnual
    });
    onComplete?.("forecast_module");
  };

  const reset = () => {
    setResult(null);
    setInputs({ targets: "", coverage: "", dosesPerPerson: "", begin: "", received: "", end: "", wasted: "", posts: "", weeks: "", sessionsPerWeek: "", vialsPerSession: "", wastageRatePct: "", dosesPerVial: "" });
  };

  return (
    <div style={{ display: "grid", gap: 12 }}>
      {completed && <div style={{ color: "#10b981", fontWeight: 700 }}><CheckCircle size={14} style={{ marginRight: 4 }} />Module completed</div>}
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={() => { setMethod("target_population"); setResult(null); }} style={{ flex: 1, padding: 10, borderRadius: 10, background: method === "target_population" ? "var(--surface-alt)" : "#fff", border: "1px solid var(--border)", fontWeight: 700, fontSize: 12 }}>Target population</button>
        <button onClick={() => { setMethod("consumption"); setResult(null); }} style={{ flex: 1, padding: 10, borderRadius: 10, background: method === "consumption" ? "var(--surface-alt)" : "#fff", border: "1px solid var(--border)", fontWeight: 700, fontSize: 12 }}>Consumption</button>
        <button onClick={() => { setMethod("immunization_session"); setResult(null); }} style={{ flex: 1, padding: 10, borderRadius: 10, background: method === "immunization_session" ? "var(--surface-alt)" : "#fff", border: "1px solid var(--border)", fontWeight: 700, fontSize: 12 }}>Session</button>
      </div>

      {method === "target_population" && (
        <>
          <Input label="Target population (Live Births or Surviving Infants)" value={inputs.targets} onChange={e => change("targets", e.target.value)} placeholder="e.g. 925" />
          <Input label="Target coverage (%)" value={inputs.coverage} onChange={e => change("coverage", e.target.value)} placeholder="e.g. 100" />
          <Input label="Number of doses per individual (schedule)" value={inputs.dosesPerPerson} onChange={e => change("dosesPerPerson", e.target.value)} placeholder="e.g. 1" />
        </>
      )}

      {method === "consumption" && (
        <>
          <Input label="Beginning balance (doses)" value={inputs.begin} onChange={e => change("begin", e.target.value)} placeholder="e.g. 30" />
          <Input label="Received during period (doses)" value={inputs.received} onChange={e => change("received", e.target.value)} placeholder="e.g. 200" />
          <Input label="Ending balance (doses)" value={inputs.end} onChange={e => change("end", e.target.value)} placeholder="e.g. 60" />
          <Input label="Wasted unopened doses" value={inputs.wasted} onChange={e => change("wasted", e.target.value)} placeholder="e.g. 0" />
        </>
      )}

      {method === "immunization_session" && (
        <>
          <Input label="Number of immunization posts" value={inputs.posts} onChange={e => change("posts", e.target.value)} placeholder="e.g. 20" />
          <Input label="Weeks of operation per year" value={inputs.weeks} onChange={e => change("weeks", e.target.value)} placeholder="e.g. 48" />
          <Input label="Sessions per week" value={inputs.sessionsPerWeek} onChange={e => change("sessionsPerWeek", e.target.value)} placeholder="e.g. 3" />
          <Input label="Average number of vials per session" value={inputs.vialsPerSession} onChange={e => change("vialsPerSession", e.target.value)} placeholder="e.g. 6" />
        </>
      )}

      <Input label="Wastage rate (%)" value={inputs.wastageRatePct} onChange={e => change("wastageRatePct", e.target.value)} placeholder="e.g. 5" />
      <Input label="Doses per vial / ampoule" value={inputs.dosesPerVial} onChange={e => change("dosesPerVial", e.target.value)} placeholder="e.g. 20 (BCG), 10 (Measles), 1 (Penta)" />

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: 10, borderRadius: 10, border: "1px solid var(--border)" }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text)" }}>Reconstituted vaccine? (BCG / Measles — needs mixing syringe)</div>
        <button onClick={() => setReconstituted(r => !r)} style={{ padding: 8, borderRadius: 8, background: reconstituted ? TILE_BLUE : "var(--surface-alt)", color: reconstituted ? "#fff" : "var(--text)", fontWeight: 700, fontSize: 12 }}>{reconstituted ? "Yes" : "No"}</button>
      </div>

      {error && <div style={{ color: "#ef4444", fontWeight: 700 }}>{error}</div>}

      {!result ? (
        <button onClick={calculate} style={{ padding: 14, borderRadius: 12, background: TILE_BLUE, color: "#fff", fontWeight: 700 }}>Calculate Forecasting</button>
      ) : (
        <>
          <Card>
            <div style={{ fontWeight: 800 }}>Forecasting results</div>
            <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 6 }}>IIP Ch 2.2.1 formulas</div>
            <div style={{ display: "grid", gap: 4, fontSize: 14 }}>
              <div>Wastage rate: {result.wastageRatePct}% → Wastage Factor {result.wastageFactor}</div>
              <div style={{ fontWeight: 700, marginTop: 6 }}>Vaccine need</div>
              <div>Annual: {result.annual} doses &nbsp;|&nbsp; Monthly: {result.monthly} doses</div>
              <div style={{ fontWeight: 700, marginTop: 6 }}>AD Syringe (1 per dose)</div>
              <div>Annual: {result.adSyringeAnnual} &nbsp;|&nbsp; Monthly: {result.adSyringeMonthly}</div>
              <div style={{ fontWeight: 700, marginTop: 6 }}>Vials needed</div>
              <div>Annual: {result.vialsAnnual}</div>
              <div style={{ fontWeight: 700, marginTop: 6 }}>Mixing syringe {reconstituted ? "" : "(N/A — not reconstituted)"}</div>
              <div>Annual: {result.mixingSyringeAnnual} &nbsp;|&nbsp; Monthly: {result.mixingSyringeMonthly}</div>
              <div style={{ fontWeight: 700, marginTop: 6 }}>Safety box</div>
              <div>Annual: {result.safetyBoxAnnual} &nbsp;|&nbsp; Monthly: {result.safetyBoxMonthly}</div>
              <div style={{ marginTop: 8, padding: 8, borderRadius: 8, background: "var(--surface-alt)", fontSize: 13 }}>
                Reminder: a separate 25% buffer stock ({result.bufferStockAnnual} doses/yr) should also be available at the facility per IIP Ch 2.3.1 — this is not multiplied into the forecast above.
              </div>
            </div>
          </Card>
          <FormulaNote
            source="IIP Ch 2.2.1"
            lines={[
              method === "target_population" && "Annual need = Target population × Coverage × Doses per person × Wastage Factor",
              method === "consumption" && "Vaccine need = (Beginning balance + Received) − (Ending balance + Wasted unopened doses)",
              method === "immunization_session" && "Annual need = Posts × Weeks × Sessions/week × Avg vials/session × Doses/vial",
              "Wastage Factor = 100 ÷ (100 − Wastage rate %)",
              "AD Syringe = 1 per dose (same as annual/monthly need)",
              "Vials needed = Total doses ÷ Doses per vial",
              reconstituted && "Mixing Syringe = Number of Vials × Wastage Factor (reconstituted vaccines only)",
              "Safety box = (Total AD Syringe + Total Mixing Syringe) × Wastage Factor ÷ 100",
              "Buffer stock (informational) = Annual need × 25%",
            ].filter(Boolean)}
          />
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setResult(null)} style={{ flex: 1, padding: 10, borderRadius: 10, background: "var(--surface-alt)" }}>New calculation</button>
            <button onClick={reset} style={{ flex: 1, padding: 10, borderRadius: 10, background: "var(--surface)", border: "1px solid var(--border)" }}>Reset</button>
          </div>
        </>
      )}
    </div>
  );
}

/* ===========================
   CHILD DOSE ELIGIBILITY CALCULATOR
   Per IIP Ch 1.2.1 routine schedule (KB-O01) + Ch 4/6 contraindication guidance:
   moderate/severe illness or high fever -> postpone; mild illness without fever
   is NOT a contraindication. Minimum interval between doses in the same series
   is 4 weeks (28 days). Uses child's date of birth + a per-dose "already given"
   log to compute, as of a chosen date, whether each scheduled dose is:
     - Postponed (illness/fever)
     - Already given
     - Not yet due (too young)
     - Waiting (previous dose in series missing or interval not yet met)
     - Eligible today
   =========================== */
const EPI_SCHEDULE = [
  { key: "bcg",      label: "BCG",        series: "BCG",     minAgeDays: 0 },
  { key: "opv0",     label: "bOPV-0",     series: "OPV",     minAgeDays: 0 },
  { key: "hepb",     label: "HepB birth dose", series: "HepB", minAgeDays: 0 },
  { key: "opv1",     label: "bOPV-1",     series: "OPV",     minAgeDays: 42,  prev: "opv0" },
  { key: "penta1",   label: "Penta-1",    series: "Penta",   minAgeDays: 42 },
  { key: "pcv1",     label: "PCV-1",      series: "PCV",     minAgeDays: 42 },
  { key: "rota1",    label: "Rota-1",     series: "Rota",    minAgeDays: 42 },
  { key: "opv2",     label: "bOPV-2",     series: "OPV",     minAgeDays: 70,  prev: "opv1" },
  { key: "penta2",   label: "Penta-2",    series: "Penta",   minAgeDays: 70,  prev: "penta1" },
  { key: "pcv2",     label: "PCV-2",      series: "PCV",     minAgeDays: 70,  prev: "pcv1" },
  { key: "rota2",    label: "Rota-2",     series: "Rota",    minAgeDays: 70,  prev: "rota1" },
  { key: "opv3",     label: "bOPV-3",     series: "OPV",     minAgeDays: 98,  prev: "opv2" },
  { key: "ipv",      label: "IPV",        series: "IPV",     minAgeDays: 98 },
  { key: "penta3",   label: "Penta-3",    series: "Penta",   minAgeDays: 98,  prev: "penta2" },
  { key: "pcv3",     label: "PCV-3",      series: "PCV",     minAgeDays: 98,  prev: "pcv2" },
  { key: "measles1", label: "Measles-1",  series: "Measles", minAgeDays: 274 },
  { key: "measles2", label: "Measles-2",  series: "Measles", minAgeDays: 457, prev: "measles1" },
];
const MIN_INTERVAL_DAYS = 28; // IIP: minimum 4-week interval between doses in a series

function daysBetween(a, b) {
  const A = new Date(a), B = new Date(b);
  if (isNaN(A.getTime()) || isNaN(B.getTime())) return null;
  return Math.round((B.getTime() - A.getTime()) / (1000 * 60 * 60 * 24));
}
function formatAge(days) {
  if (days == null) return "-";
  const months = Math.floor(days / 30.4375);
  const weeks = Math.floor(days / 7);
  if (days < 70) return `${days} day(s) (~${weeks} week(s))`;
  return `${days} day(s) (~${months} month(s))`;
}

function EligibilityCalculator({ onComplete, completed }) {
  const [dob, setDob] = useState("");
  const [asOf, setAsOf] = useState(() => new Date().toISOString().slice(0, 10));
  const [feverToday, setFeverToday] = useState(false);
  const [seriousIllness, setSeriousIllness] = useState(false);
  const [doseLog, setDoseLog] = useState({}); // key -> { given: bool, dateGiven: "yyyy-mm-dd" }
  const [results, setResults] = useState(null);
  const [error, setError] = useState("");

  const setDose = (key, field, val) =>
    setDoseLog(d => ({ ...d, [key]: { ...(d[key] || { given: false, dateGiven: "" }), [field]: val } }));

  const calculate = () => {
    setError("");
    if (!dob) return setError("Enter the child's date of birth.");
    const ageDays = daysBetween(dob, asOf);
    if (ageDays == null || ageDays < 0) return setError("Check the date of birth / visit date.");
    const postponeReason = feverToday
      ? "Postpone visit — child has fever today (recheck when fever resolves)"
      : (seriousIllness ? "Postpone visit — moderate/severe illness reported" : null);

    const rows = EPI_SCHEDULE.map(item => {
      const mine = doseLog[item.key] || { given: false, dateGiven: "" };
      if (postponeReason) {
        return { ...item, status: "postponed", message: postponeReason };
      }
      if (mine.given) {
        return { ...item, status: "given", message: `Already given${mine.dateGiven ? " on " + mine.dateGiven : ""}` };
      }
      if (ageDays < item.minAgeDays) {
        return { ...item, status: "too_young", message: `Not yet due — needs ${item.minAgeDays} day(s) of age (currently ${formatAge(ageDays)})` };
      }
      if (item.prev) {
        const prevLog = doseLog[item.prev] || { given: false, dateGiven: "" };
        if (!prevLog.given) {
          return { ...item, status: "waiting", message: `Waiting — previous dose (${EPI_SCHEDULE.find(s => s.key === item.prev)?.label}) not yet recorded` };
        }
        if (prevLog.dateGiven) {
          const sinceInterval = daysBetween(prevLog.dateGiven, asOf);
          if (sinceInterval != null && sinceInterval < MIN_INTERVAL_DAYS) {
            return { ...item, status: "waiting", message: `Waiting — minimum ${MIN_INTERVAL_DAYS}-day interval since previous dose not yet met (${sinceInterval} day(s) so far)` };
          }
        }
      }
      return { ...item, status: "eligible", message: `Eligible for ${item.label} today` };
    });
    setResults({ ageDays, rows });
    if (onComplete) onComplete("eligibility_module");
  };

  const STATUS_STYLE = {
    eligible:  { bg: "#DCFCE7", fg: "#166534", label: "Eligible today" },
    postponed: { bg: "#FEE2E2", fg: "#991B1B", label: "Postponed" },
    given:     { bg: "#E2E8F0", fg: "var(--text)", label: "Already given" },
    too_young: { bg: "#FEF9C3", fg: "#854D0E", label: "Not yet due" },
    waiting:   { bg: "#FEF3C7", fg: "#92400E", label: "Waiting" },
  };

  return (
    <Card style={{ marginBottom: 12 }}>
      <div style={{ fontWeight: 800, marginBottom: 8 }}>Child Dose Eligibility Calculator</div>
      <div style={{ color: "var(--text-muted)", fontSize: 12, marginBottom: 10 }}>
        Enter the child's date of birth and today's visit date, log any doses already given, and flag illness/fever to check today's eligibility per dose. (IIP Ch 1.2.1, Ch 4/6)
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        <Input label="Child's date of birth" type="date" value={dob} onChange={e => setDob(e.target.value)} />
        <Input label="Visit date" type="date" value={asOf} onChange={e => setAsOf(e.target.value)} />
      </div>
      <div style={{ display: "flex", gap: 16, marginTop: 10, flexWrap: "wrap" }}>
        <label style={{ display: "flex", gap: 6, alignItems: "center", fontSize: 13 }}>
          <input type="checkbox" checked={feverToday} onChange={e => setFeverToday(e.target.checked)} />
          Child has fever today
        </label>
        <label style={{ display: "flex", gap: 6, alignItems: "center", fontSize: 13 }}>
          <input type="checkbox" checked={seriousIllness} onChange={e => setSeriousIllness(e.target.checked)} />
          Moderate/severe illness (non-fever)
        </label>
      </div>

      <div style={{ marginTop: 14, fontWeight: 700, fontSize: 13 }}>Doses already given</div>
      <div style={{ display: "grid", gap: 8, marginTop: 6 }}>
        {EPI_SCHEDULE.map(item => (
          <div key={item.key} style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
            <label style={{ display: "flex", gap: 6, alignItems: "center", fontSize: 13, minWidth: 140 }}>
              <input type="checkbox" checked={!!(doseLog[item.key] && doseLog[item.key].given)}
                onChange={e => setDose(item.key, "given", e.target.checked)} />
              {item.label}
            </label>
            {doseLog[item.key] && doseLog[item.key].given && (
              <input type="date" value={doseLog[item.key].dateGiven || ""}
                onChange={e => setDose(item.key, "dateGiven", e.target.value)}
                style={{ padding: 8, borderRadius: 8, border: "1px solid var(--border)", background: "var(--surface)", color: "var(--text)" }} />
            )}
          </div>
        ))}
      </div>

      {error && <div style={{ color: ICON_RED, marginTop: 10, fontSize: 13 }}>{error}</div>}

      <div style={{ marginTop: 12 }}>
        <button onClick={calculate} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", border: "none", fontWeight: 700 }}>
          Check eligibility
        </button>
      </div>

      {results && (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 8 }}>Child's age as of visit date: {formatAge(results.ageDays)}</div>
          <div style={{ display: "grid", gap: 8 }}>
            {results.rows.map(r => {
              const st = STATUS_STYLE[r.status];
              return (
                <div key={r.key} style={{ background: st.bg, color: st.fg, borderRadius: 10, padding: "8px 12px" }}>
                  <div style={{ fontWeight: 800, fontSize: 13 }}>{r.label} — {st.label}</div>
                  <div style={{ fontSize: 12 }}>{r.message}</div>
                </div>
              );
            })}
          </div>
          <FormulaNote
            source="IIP Ch 1.2.1 (routine schedule), Ch 4/6 (contraindications)"
            lines={[
              "Age (days) = Visit date − Date of birth",
              "Eligible when: Age ≥ minimum age for the dose AND previous dose in series already given AND ≥ 28 days since that previous dose",
              "Postponed when: fever today OR moderate/severe illness reported (overrides all other checks)",
            ]}
          />
        </div>
      )}

      {completed && <div style={{ marginTop: 10, color: "#16A34A", fontWeight: 700, fontSize: 12 }}>✓ Completed</div>}
    </Card>
  );
}

/* ===========================
   MULTI-VACCINE FORECAST TABLE — replicates IIP Table 2.2 / 2.3 (Example 2.1)
   Computes Annual/Monthly need, AD syringe, Mixing syringe & Safety box across
   all EPI antigens at once from a single catchment population, the way the
   manual's worked examples and exercises (2.1/2.4) actually do it.
   =========================== */
const ANTIGENS = [
  { name: "BCG", base: "lb", doses: 1, wmf: 2, coverage: 1, adSyringe: true, dosesPerVial: 20, mixing: true },
  { name: "bOPV", base: "lb", doses: 4, wmf: 1.11, coverage: 1, adSyringe: false, dosesPerVial: null, mixing: false },
  { name: "IPV", base: "si", doses: 2, wmf: 1.11, coverage: 1, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "Pentavalent", base: "si", doses: 3, wmf: 1.05, coverage: 1, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "Hep B birth dose", base: "lb", doses: 1, wmf: 1.05, coverage: 1, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "Measles", base: "si", doses: 2, wmf: 1.54, coverage: 1, adSyringe: true, dosesPerVial: 10, mixing: true },
  { name: "PCV-13", base: "si", doses: 3, wmf: 1.11, coverage: 1, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "Rota", base: "si", doses: 3, wmf: 1.11, coverage: 1, adSyringe: false, dosesPerVial: null, mixing: false },
  { name: "Td", base: "lb", doses: 3, wmf: 1.11, coverage: 1, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "Pfizer (COVID-19)", base: "pfizer", doses: 2, wmf: 1.11, coverage: 0.70, adSyringe: true, dosesPerVial: null, mixing: false },
  { name: "HPV", base: "hpv", doses: 1, wmf: 1.05, coverage: 0.95, adSyringe: true, dosesPerVial: null, mixing: false },
];
const AD_SYRINGE_WMF = 1.05; // IIP Table 2.3 uses a uniform 1.05 wastage factor for AD/mixing syringe & safety box calcs

function MultiVaccineForecastTable({ onComplete }) {
  const [population, setPopulation] = useState("");
  const [lbPct, setLbPct] = useState("");
  const [siPct, setSiPct] = useState("");
  const [pfizerPct, setPfizerPct] = useState("");
  const [hpvPct, setHpvPct] = useState("");
  const [rows, setRows] = useState(null);
  const [err, setErr] = useState("");

  const calc = () => {
    const pop = Number(population || 0);
    if (pop <= 0) return setErr("Enter a valid catchment population.");
    setErr("");
    const lb = Math.round(pop * (Number(lbPct || 3.7) / 100));
    const si = Math.round(pop * (Number(siPct || 3.2) / 100));
    const pf = Math.round(pop * (Number(pfizerPct || 64) / 100));
    const hp = Math.round(pop * (Number(hpvPct || 1.4) / 100));

    const baseVal = { lb, si, pfizer: pf, hpv: hp };

    let totalAdSyringe = 0, totalMixing = 0;
    const computed = ANTIGENS.map(v => {
      const target = baseVal[v.base];
      const annual = Math.ceil(target * v.coverage * v.doses * v.wmf);
      const monthly = Math.ceil(annual / 12);
      let adSyringeAnnual = 0, mixingAnnual = 0;
      if (v.adSyringe) {
        adSyringeAnnual = Math.ceil(target * v.coverage * v.doses * AD_SYRINGE_WMF);
        totalAdSyringe += adSyringeAnnual;
      }
      if (v.mixing) {
        const vials = Math.ceil(annual / v.dosesPerVial);
        mixingAnnual = Math.ceil(vials * AD_SYRINGE_WMF);
        totalMixing += mixingAnnual;
      }
      return { ...v, target, annual, monthly, adSyringeAnnual, mixingAnnual };
    });

    const safetyBoxAnnual = Math.ceil(((totalAdSyringe + totalMixing) * AD_SYRINGE_WMF) / 100);
    const safetyBoxMonthly = Math.ceil(safetyBoxAnnual / 12);

    setRows({ computed, totalAdSyringe, totalMixing, safetyBoxAnnual, safetyBoxMonthly, lb, si, pf, hp });
    onComplete?.("forecast_module");
  };

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div style={{ fontSize: 12, color: "var(--text-muted)" }}>Replicates IIP Table 2.2/2.3 (Example 2.1) — computes all antigens from one catchment population.</div>
      <Input label="Catchment population" value={population} onChange={e => setPopulation(e.target.value)} placeholder="e.g. 25000" />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Input label="% Live Birth" value={lbPct} onChange={e => setLbPct(e.target.value)} placeholder="e.g. 3.7" />
        <Input label="% Surviving Infant" value={siPct} onChange={e => setSiPct(e.target.value)} placeholder="e.g. 3.2" />
        <Input label="% for Pfizer target (COVID)" value={pfizerPct} onChange={e => setPfizerPct(e.target.value)} placeholder="e.g. 64" />
        <Input label="% for HPV target" value={hpvPct} onChange={e => setHpvPct(e.target.value)} placeholder="e.g. 1.4" />
      </div>
      {err && <div style={{ color: "#ef4444", fontWeight: 700 }}>{err}</div>}
      <button onClick={calc} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", fontWeight: 700 }}>Generate Facility Table</button>

      {rows && (
        <div style={{ display: "grid", gap: 8 }}>
          <div style={{ fontSize: 12, color: "var(--text-muted)" }}>Live Birth: {rows.lb} · Surviving Infant: {rows.si} · Pfizer target: {rows.pf} · HPV target: {rows.hp}</div>
          <div style={{ overflowX: "auto" }}>
            <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 12 }}>
              <thead>
                <tr style={{ background: "var(--surface-alt)" }}>
                  <th style={{ textAlign: "left", padding: 6 }}>Vaccine</th>
                  <th style={{ padding: 6 }}>Target</th>
                  <th style={{ padding: 6 }}>Annual</th>
                  <th style={{ padding: 6 }}>Monthly</th>
                  <th style={{ padding: 6 }}>AD Syr.</th>
                  <th style={{ padding: 6 }}>Mixing Syr.</th>
                </tr>
              </thead>
              <tbody>
                {rows.computed.map(r => (
                  <tr key={r.name} style={{ borderTop: "1px solid var(--border)" }}>
                    <td style={{ padding: 6, fontWeight: 700 }}>{r.name}</td>
                    <td style={{ padding: 6, textAlign: "center" }}>{r.target}</td>
                    <td style={{ padding: 6, textAlign: "center" }}>{r.annual}</td>
                    <td style={{ padding: 6, textAlign: "center" }}>{r.monthly}</td>
                    <td style={{ padding: 6, textAlign: "center" }}>{r.adSyringeAnnual || "—"}</td>
                    <td style={{ padding: 6, textAlign: "center" }}>{r.mixingAnnual || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <Card>
            <div style={{ fontWeight: 800 }}>Facility totals</div>
            <div>Total AD Syringes (annual): {rows.totalAdSyringe}</div>
            <div>Total Mixing Syringes (annual, BCG + Measles): {rows.totalMixing}</div>
            <div style={{ fontWeight: 700, marginTop: 4 }}>Safety box — Annual: {rows.safetyBoxAnnual} · Monthly: {rows.safetyBoxMonthly}</div>
          </Card>
          <FormulaNote
            source="IIP Ch 2.2.1, Table 2.2/2.3 (Example 2.1)"
            lines={[
              "Target = Catchment population × Base-population % (Live Birth / Surviving Infant / Pfizer / HPV)",
              "Annual need (per antigen) = Target × Coverage × Doses in schedule × Wastage Multiplication Factor (WMF)",
              "AD Syringe (annual) = Target × Coverage × Doses × 1.05 (uniform syringe WMF)",
              "Mixing Syringe (annual) = ⌈Annual doses ÷ Doses per vial⌉ × 1.05 (BCG & Measles only)",
              "Safety box (annual) = (Total AD Syringes + Total Mixing Syringes) × 1.05 ÷ 100",
            ]}
          />
        </div>
      )}
    </div>
  );
}

/* ===========================
   STOCK LEVEL CALCULATOR (IIP Ch 2.3.1)
   Safety stock = need * 25%
   Minimum stock = Safety stock + Lead time consumption (need/4)
   Maximum stock = need + Safety stock
   =========================== */
function StockLevelCalculator({ onComplete, completed }) {
  const [need, setNeed] = useState("");
  const [result, setResult] = useState(null);
  const [err, setErr] = useState("");

  const calc = () => {
    const n = Number(need || 0);
    if (n <= 0) return setErr("Enter the requirement for the supply period (doses).");
    setErr("");
    const safety = Math.ceil(n * 0.25);
    const leadTimeConsumption = Math.ceil(n / 4);
    const minimum = safety + leadTimeConsumption;
    const maximum = n + safety;
    setResult({ safety, leadTimeConsumption, minimum, maximum });
    onComplete?.("stock_module");
  };

  return (
    <div style={{ display: "grid", gap: 10 }}>
      {completed && <div style={{ color: "#10b981", fontWeight: 700 }}><CheckCircle size={14} style={{ marginRight: 4 }} />Module completed</div>}
      <Input label="Requirement for the supply period (doses)" value={need} onChange={e => setNeed(e.target.value)} placeholder="e.g. 205 (monthly vaccine need)" />
      {err && <div style={{ color: "#ef4444" }}>{err}</div>}
      <button onClick={calc} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", fontWeight: 700 }}>Calculate Stock Levels</button>

      {result && (
        <Card>
          <div style={{ fontWeight: 800 }}>Stock levels</div>
          <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 6 }}>IIP Ch 2.3.1</div>
          <div style={{ display: "grid", gap: 4 }}>
            <div>Safety stock (25% of need): {result.safety} doses</div>
            <div>Lead time consumption (need ÷ 4): {result.leadTimeConsumption} doses</div>
            <div style={{ fontWeight: 700 }}>Minimum stock level: {result.minimum} doses</div>
            <div style={{ fontWeight: 700 }}>Maximum stock level: {result.maximum} doses</div>
          </div>
          <FormulaNote
            source="IIP Ch 2.3.1"
            lines={[
              "Safety stock = Need for supply period × 25%",
              "Lead time consumption = Need for supply period ÷ 4",
              "Minimum stock = Safety stock + Lead time consumption",
              "Maximum stock = Need for supply period + Safety stock",
            ]}
          />
        </Card>
      )}
    </div>
  );
}

/* Wastage calculation: VUR / VWR and wastage factor — IIP Ch 2.4.1 */
function WastageCalculator({ onComplete }) {
  const [start, setStart] = useState("");
  const [received, setReceived] = useState("");
  const [end, setEnd] = useState("");
  const [admin, setAdmin] = useState("");
  const [result, setResult] = useState(null);
  const [err, setErr] = useState("");

  const calc = () => {
    const s = Number(start || 0), r = Number(received || 0), e = Number(end || 0), a = Number(admin || 0);
    const available = s + r - e;
    if (available <= 0) return setErr("Available doses (start + received − end) must be > 0.");
    if (a < 0) return setErr("Doses administered must be ≥ 0.");
    setErr("");
    const VUR = (a / available) * 100; // IIP Ch 2.4.1
    const VWR = 100 - VUR;
    const wastageFactor = VWR >= 100 ? null : Number((100 / (100 - VWR)).toFixed(3));
    setResult({ used: Math.round(available), VUR: VUR.toFixed(1), VWR: VWR.toFixed(1), wastageFactor });
    onComplete?.("stock_module");
  };

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <Input label="Beginning balance (doses)" value={start} onChange={e => setStart(e.target.value)} placeholder="e.g. 30" />
      <Input label="Received during period (doses)" value={received} onChange={e => setReceived(e.target.value)} placeholder="e.g. 200" />
      <Input label="Ending balance (doses)" value={end} onChange={e => setEnd(e.target.value)} placeholder="e.g. 60" />
      <Input label="Number of doses administered (children immunized)" value={admin} onChange={e => setAdmin(e.target.value)} placeholder="e.g. 130" />
      {err && <div style={{ color: "#ef4444" }}>{err}</div>}
      <button onClick={calc} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", fontWeight: 700 }}>Calculate Wastage</button>

      {result && (
        <Card>
          <div style={{ fontWeight: 800 }}>Wastage summary</div>
          <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 6 }}>IIP Ch 2.4.1</div>
          <div style={{ display: "grid", gap: 4 }}>
            <div>Doses available for use: {result.used}</div>
            <div>Vaccine Usage Rate (VUR): {result.VUR}%</div>
            <div>Vaccine Wastage Rate (VWR): {result.VWR}%</div>
            <div>Wastage Factor: {result.wastageFactor ?? "N/A"}</div>
          </div>
          <FormulaNote
            source="IIP Ch 2.4.1"
            lines={[
              "Doses available = Beginning balance + Received − Ending balance",
              "Vaccine Usage Rate (VUR) = (Doses administered ÷ Doses available) × 100",
              "Vaccine Wastage Rate (VWR) = 100 − VUR",
              "Wastage Factor = 100 ÷ (100 − VWR)",
            ]}
          />
        </Card>
      )}
    </div>
  );
}

/* MDVP & VVM checkers (IIP Ch 2.4.2 / 2.6.2) */
function MDVPChecker({ onChangeComplete }) {
  const criteria = [
    { key: "notMeaslesBcg", label: "Vaccine is NOT BCG or Measles (reconstituted)?" },
    { key: "prequalified", label: "WHO prequalified?" },
    { key: "approved28", label: "Approved for use up to 28 days after opening?" },
    { key: "expiry", label: "Expiry date has not passed?" },
    { key: "stored", label: "Stored at +2°C to +8°C?" },
    { key: "vvm", label: "VVM not at or past discard point?" },
    { key: "notFrozen", label: "Not damaged by freezing?" },
  ];
  const [answers, setAnswers] = useState({});
  const answeredAll = criteria.every(c => answers[c.key] !== undefined);
  const allYes = answeredAll && criteria.every(c => answers[c.key] === true);

  useEffect(() => { if (answeredAll) onChangeComplete?.(allYes); }, [answeredAll]); // eslint-disable-line

  return (
    <div style={{ display: "grid", gap: 8 }}>
      <div style={{ fontWeight: 700 }}>MDVP checklist</div>
      <div style={{ fontSize: 12, color: "var(--text-muted)" }}>IIP Ch 2.4.2 — Ethiopia applies MDVP to bOPV, IPV, Td, PCV-13.</div>
      {criteria.map(c => (
        <div key={c.key} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: 10, borderRadius: 10, border: "1px solid var(--border)", background: "var(--surface)" }}>
          <div style={{ fontSize: 13 }}>{c.label}</div>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setAnswers(a => ({ ...a, [c.key]: true }))} style={{ padding: 8, borderRadius: 8, background: answers[c.key] === true ? "#10b981" : "var(--surface-alt)", color: answers[c.key] === true ? "#fff" : "var(--text)" }}>Yes</button>
            <button onClick={() => setAnswers(a => ({ ...a, [c.key]: false }))} style={{ padding: 8, borderRadius: 8, background: answers[c.key] === false ? "#ef4444" : "var(--surface-alt)", color: answers[c.key] === false ? "#fff" : "var(--text)" }}>No</button>
          </div>
        </div>
      ))}
      {answeredAll && (
        <>
          <Card style={{ background: allYes ? "#E6F7F1" : "#FEE2E2", borderColor: allYes ? "#10b981" : "#ef4444" }}>
            {allYes ? "This vial may be kept and used up to 28 days after opening (meets MDVP criteria)." : "Do NOT keep — criteria not met. Discard within 6 hours of opening / end of session (if reconstituted) or immediately if any other criterion fails."}
          </Card>
          <FormulaNote
            source="IIP Ch 2.4.2"
            lines={["Rule: Keep for up to 28 days only if ALL 7 MDVP criteria = Yes. Any single \"No\" → discard."]}
          />
        </>
      )}
    </div>
  );
}

function VVMChecker({ onChangeComplete }) {
  const [stage, setStage] = useState(null);
  useEffect(() => { if (stage) onChangeComplete?.(stage <= 2); }, [stage]); // eslint-disable-line

  return (
    <div style={{ display: "grid", gap: 8 }}>
      <div style={{ fontWeight: 700 }}>VVM stage checker</div>
      <div style={{ fontSize: 12, color: "var(--text-muted)" }}>IIP Ch 2.6.2 — inner square vs. outer circle color.</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <button onClick={() => setStage(1)} style={{ padding: 12, borderRadius: 10, background: "#E6F7F1", border: "1px solid #10b981" }}>Stage 1 — square lighter</button>
        <button onClick={() => setStage(2)} style={{ padding: 12, borderRadius: 10, background: "#E6F7F1", border: "1px solid #10b981" }}>Stage 2 — square lighter</button>
        <button onClick={() => setStage(3)} style={{ padding: 12, borderRadius: 10, background: "#FEE2E2", border: "1px solid #ef4444" }}>Stage 3 — square = circle</button>
        <button onClick={() => setStage(4)} style={{ padding: 12, borderRadius: 10, background: "#FEE2E2", border: "1px solid #ef4444" }}>Stage 4 — square darker</button>
      </div>
      {stage && (
        <>
          <Card>{stage <= 2 ? "Safe to use (VVM within acceptable stage)." : "Discard — VVM at or past the discard point."}</Card>
          <FormulaNote
            source="IIP Ch 2.6.2"
            lines={["Rule: Stage 1–2 (inner square lighter than outer circle) = safe to use. Stage 3–4 (square = circle or darker) = discard."]}
          />
        </>
      )}
    </div>
  );
}

/* ===========================
   TEMPERATURE EXCURSION HELPER (DT-1) — IIP Ch 2.6.3 action table
   Reproduces the manual's full branching action list for refrigerator readings.
   =========================== */
function rangeFromTemp(tempC) {
  if (tempC < 2) return "below2";
  if (tempC <= 8) return "normal";
  if (tempC <= 10) return "8to10";
  return "above10";
}

function TemperatureExcursionHelper() {
  const [range, setRange] = useState(null);
  const [readings, setReadings] = useState({ morning: "", evening: "" });
  const [log, setLog] = useState([]); // {period, value, range, time}
  const [readError, setReadError] = useState("");

  const ranges = [
    { key: "below2", label: "Below +2°C" },
    { key: "normal", label: "+2°C to +8°C (normal)" },
    { key: "8to10", label: "+8°C to +10°C" },
    { key: "above10", label: "Above +10°C" },
  ];

  const actions = {
    below2: [
      "Follow the refrigerator closely.",
      "Electric: turn the thermostat knob to a lower number. Kerosene: decrease the flame size.",
      "Move vaccines to safe storage immediately (apply the contingency plan).",
      "Check freeze-sensitive vaccines for freezing damage using the Shake Test.",
    ],
    normal: ["No action needed — continue routine twice-daily monitoring."],
    "8to10": [
      "If this followed a temporary power failure, no further action is necessary.",
      "Confirm the refrigeration unit is working; monitor closely and act if still out of range at the next check.",
    ],
    above10: [
      "Report to your supervisor immediately.",
      "Confirm the refrigerator is working; check the power supply (electricity/kerosene/solar).",
      "Check the door seal — if broken, call a technician.",
      "Check for frost blocking cold air from the freezer compartment; defrost if needed.",
      "If the fridge is otherwise fine, turn the thermostat to a higher (cooler) number — never do this right after a power cut, to avoid freezing.",
      "If +2°C to +8°C still cannot be maintained, move vaccines to other cold chain equipment until repaired.",
    ],
  };

  const ACTION_HEADLINE = {
    below2: "Move vaccines to a cold box immediately with conditioned ice packs.",
    normal: "Continue routine monitoring.",
    "8to10": "Monitor closely — confirm the fridge is working.",
    above10: "Move vaccines to safe cold chain storage and report immediately.",
  };

  const recordReading = (period) => {
    setReadError("");
    const raw = readings[period];
    const val = parseFloat(raw);
    if (raw === "" || isNaN(val)) { setReadError("Enter a numeric temperature reading (e.g. +5 or 10)."); return; }
    const r = rangeFromTemp(val);
    setRange(r);
    setLog(l => [{ period, value: val, range: r, time: new Date().toLocaleString() }, ...l].slice(0, 10));
  };

  return (
    <div style={{ display: "grid", gap: 8 }}>
      <div style={{ fontWeight: 700 }}>Temperature excursion action helper</div>
      <div style={{ fontSize: 12, color: "var(--text-muted)" }}>IIP Ch 2.6.3 — enter the fridge reading (morning/evening check) or select a range to see required actions.</div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 8, alignItems: "end" }}>
        <Input label="Morning reading (°C)" type="number" value={readings.morning} placeholder="e.g. 5"
          onChange={e => setReadings(r => ({ ...r, morning: e.target.value }))} />
        <button onClick={() => recordReading("morning")} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", border: "none", fontWeight: 700, height: 46 }}>Record</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 8, alignItems: "end" }}>
        <Input label="Evening reading (°C)" type="number" value={readings.evening} placeholder="e.g. 10"
          onChange={e => setReadings(r => ({ ...r, evening: e.target.value }))} />
        <button onClick={() => recordReading("evening")} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", border: "none", fontWeight: 700, height: 46 }}>Record</button>
      </div>
      {readError && <div style={{ color: ICON_RED, fontSize: 12 }}>{readError}</div>}

      <div style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}>Or select a reading directly:</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        {ranges.map(r => (
          <button key={r.key} onClick={() => setRange(r.key)} style={{ padding: 10, borderRadius: 10, border: range === r.key ? `2px solid ${TILE_BLUE}` : "1px solid var(--border)", background: range === r.key ? "#EAF1F8" : "#fff", fontSize: 12, fontWeight: 700 }}>{r.label}</button>
        ))}
      </div>

      {range && (
        <>
          <Card style={{ background: range === "normal" ? "#E6F7F1" : (range === "8to10" ? "#FEF9C3" : "#FEE2E2") }}>
            <div style={{ fontWeight: 800, marginBottom: 6 }}>{ACTION_HEADLINE[range]}</div>
            <ul style={{ margin: 0, paddingLeft: 18, display: "grid", gap: 4 }}>
              {actions[range].map((a, i) => <li key={i} style={{ fontSize: 13 }}>{a}</li>)}
            </ul>
          </Card>
          <FormulaNote
            source="IIP Ch 2.6.3"
            lines={["Rule: reading < 2°C → below range; 2–8°C → normal; >8–10°C → mildly high; >10°C → above range. Range determines the action list shown."]}
          />
        </>
      )}

      {log.length > 0 && (
        <div style={{ marginTop: 6 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: "var(--text)", marginBottom: 4 }}>Recent readings</div>
          <div style={{ display: "grid", gap: 4 }}>
            {log.map((entry, i) => (
              <div key={i} style={{ fontSize: 12, color: "var(--text-muted)" }}>
                {entry.time} — {entry.period === "morning" ? "Morning" : "Evening"}: {entry.value}°C ({ranges.find(r => r.key === entry.range)?.label})
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ===========================
   SHAKE TEST DECISION TREE — IIP Ch 2.6.4
   Step-by-step checklist for suspected freeze-damaged vaccine vials.
   =========================== */
function ShakeTestChecker() {
  const [frozeControl, setFrozeControl] = useState(null); // step 1: control vial prepared?
  const [sedimentFaster, setSedimentFaster] = useState(null); // step 2: suspect sediments same/faster than control?

  const reset = () => { setFrozeControl(null); setSedimentFaster(null); };

  return (
    <div style={{ display: "grid", gap: 8 }}>
      <div style={{ fontWeight: 700 }}>Shake Test decision tree</div>
      <div style={{ fontSize: 12, color: "var(--text-muted)" }}>IIP Ch 2.6.4 — use when a freeze-sensitive vaccine (IPV, Penta, PCV-13, HepB, Td) may have been frozen.</div>

      <div style={{ padding: 10, borderRadius: 10, border: "1px solid var(--border)", background: "var(--surface)" }}>
        <div style={{ fontSize: 13, marginBottom: 8 }}>Step 1: Do you have a control vial (same vaccine, deliberately frozen solid then thawed)?</div>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setFrozeControl(true)} style={{ padding: 8, borderRadius: 8, background: frozeControl === true ? TILE_BLUE : "var(--surface-alt)", color: frozeControl === true ? "#fff" : "var(--text)" }}>Yes</button>
          <button onClick={() => setFrozeControl(false)} style={{ padding: 8, borderRadius: 8, background: frozeControl === false ? "#ef4444" : "var(--surface-alt)", color: frozeControl === false ? "#fff" : "var(--text)" }}>No</button>
        </div>
      </div>

      {frozeControl === false && (
        <Card style={{ background: "#FEF9C3" }}>Prepare a control vial first: freeze it solid, let it thaw, then shake both vials vigorously for 10-15 seconds and let them stand 5-15 minutes before comparing.</Card>
      )}

      {frozeControl === true && (
        <div style={{ padding: 10, borderRadius: 10, border: "1px solid var(--border)", background: "var(--surface)" }}>
          <div style={{ fontSize: 13, marginBottom: 8 }}>Step 2: After shaking and letting both vials stand, did the suspect vial sediment at the same rate or faster than the control vial?</div>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setSedimentFaster(true)} style={{ padding: 8, borderRadius: 8, background: sedimentFaster === true ? "#ef4444" : "var(--surface-alt)", color: sedimentFaster === true ? "#fff" : "var(--text)" }}>Yes</button>
            <button onClick={() => setSedimentFaster(false)} style={{ padding: 8, borderRadius: 8, background: sedimentFaster === false ? "#10b981" : "var(--surface-alt)", color: sedimentFaster === false ? "#fff" : "var(--text)" }}>No</button>
          </div>
        </div>
      )}

      {sedimentFaster === true && (
        <>
          <Card style={{ background: "#FEE2E2", borderColor: "#ef4444" }}>
            <div style={{ fontWeight: 800 }}>Discard this vial — it has freeze damage.</div>
            <div style={{ fontSize: 13, marginTop: 4 }}>Same-rate or faster sedimentation confirms the vial was frozen. Discard it and check the rest of the batch stored the same way.</div>
          </Card>
          <FormulaNote source="IIP Ch 2.6.4" lines={["Rule: Suspect vial sediments at the same rate as or faster than the known-frozen control vial → discard."]} />
        </>
      )}
      {sedimentFaster === false && (
        <>
          <Card style={{ background: "#E6F7F1", borderColor: "#10b981" }}>
            <div style={{ fontWeight: 800 }}>Safe to use — this vial was not frozen.</div>
            <div style={{ fontSize: 13, marginTop: 4 }}>Slower sedimentation than the control means the vial is undamaged and safe to use.</div>
          </Card>
          <FormulaNote source="IIP Ch 2.6.4" lines={["Rule: Suspect vial sediments slower than the known-frozen control vial → safe to use."]} />
        </>
      )}

      {(frozeControl !== null) && (
        <button onClick={reset} style={{ padding: 8, borderRadius: 8, background: "var(--surface-alt)", border: "none", color: "var(--text)", fontSize: 12, width: "fit-content" }}>Start over</button>
      )}
    </div>
  );
}

/* ===========================
   Scenario player (IIP Ch 2.6 case scenarios / decision trees) & mini-assessment
   =========================== */
const SCENARIOS = [
  {
    id: "SC-1", title: "Morning temperature alarm (Ch 2.6–2.7)",
    steps: [{
      text: "You arrive and find the vaccine refrigerator reading +11°C. What do you do first?",
      options: [
        "Check VVMs, move vaccines to a functioning fridge/cold box with conditioned ice packs, record and notify the officer",
        "Wait until tomorrow to see if it improves",
        "Throw away all vaccines immediately without checking anything"
      ]
    }],
    outcomes: {
      "0_0": { correct: true, text: "Correct. Safeguard the vaccines first, check VVM status, then document and report (IIP Ch 2.6-2.7)." },
      "0_1": { correct: false, text: "Incorrect. A high-temperature excursion needs immediate action — vaccines must be safeguarded right away." },
      "0_2": { correct: false, text: "Incorrect. Don't discard without checking VVM status first — only discard vials that fail the checks." },
    }
  },
  {
    id: "SC-2", title: "Possible frozen Penta (Ch 2.6.4)",
    steps: [{
      text: "Penta vials were stored overnight near the freezer compartment and are suspected frozen. What should you do?",
      options: [
        "Perform the Shake Test against a control vial known never to have been frozen",
        "Use the vials anyway since they still look liquid",
        "Discard all vials in the fridge without testing"
      ]
    }],
    outcomes: {
      "0_0": { correct: true, text: "Correct. The Shake Test compares suspect vs. control sedimentation — same/faster sedimentation confirms freezing (IIP Ch 2.6.4)." },
      "0_1": { correct: false, text: "Incorrect. Appearance alone does not confirm freezing damage — perform the Shake Test." },
      "0_2": { correct: false, text: "Incorrect. Only vials that fail the Shake Test should be discarded; testing avoids unnecessary wastage." },
    }
  },
  {
    id: "SC-3", title: "Defaulter identified during micro-planning (Ch 4.2–4.3)",
    steps: [{
      text: "While updating the catchment register, you find a child who missed the Penta-2 dose two months ago and has not returned. What is the correct next step?",
      options: [
        "Flag the child as a defaulter, prioritize the area in the micro-plan, and follow up for catch-up vaccination",
        "Remove the child from the register since the dose was missed",
        "Wait for the caregiver to bring the child in on their own with no follow-up"
      ]
    }],
    outcomes: {
      "0_0": { correct: true, text: "Correct. Defaulter tracking identifies missed doses so they can be followed up; micro-planning prioritizes areas with the highest number of zero-dose/under-immunized children (IIP Ch 4.2/4.3)." },
      "0_1": { correct: false, text: "Incorrect. A missed dose must be tracked as a defaulter, not removed from the register." },
      "0_2": { correct: false, text: "Incorrect. Passive waiting does not fulfil the facility's responsibility to actively follow up defaulters." },
    }
  },
];

function ScenarioPlayer({ scenario, onBack, onComplete }) {
  const [stepIdx] = useState(0);
  const [finished, setFinished] = useState(false);
  const [outcome, setOutcome] = useState(null);

  const choose = (i) => {
    const key = `${stepIdx}_${i}`;
    const res = scenario.outcomes[key];
    setOutcome(res);
    setFinished(true);
    onComplete?.("scenario_module");
  };

  if (finished) {
    return (
      <div style={{ display: "grid", gap: 10 }}>
        <Card>
          <div style={{ fontWeight: 800 }}>{outcome.correct ? "Correct" : "Incorrect"}</div>
          <div style={{ marginTop: 8 }}>{outcome.text}</div>
        </Card>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => { setFinished(false); setOutcome(null); }} style={{ padding: 10, borderRadius: 8, background: "var(--surface-alt)" }}>Try again</button>
        </div>
      </div>
    );
  }

  const step = scenario.steps[stepIdx];
  return (
    <Card>
      <div style={{ fontWeight: 800 }}>{scenario.title}</div>
      <div style={{ color: "var(--text-muted)", marginTop: 8 }}>{step.text}</div>
      <div style={{ marginTop: 10, display: "grid", gap: 8 }}>
        {step.options.map((o, i) => <button key={i} onClick={() => choose(i)} style={{ padding: 12, borderRadius: 10, border: "1px solid var(--border)", background: "var(--surface)", textAlign: "left" }}>{o}</button>)}
      </div>
    </Card>
  );
}

function MiniAssessment({ onComplete, existing = 0 }) {
  const [idx, setIdx] = useState(0);
  const [selected, setSelected] = useState(null);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  const q = QUIZ[idx];

  const submit = () => {
    if (selected === null) return;
    const correct = selected === q.correct;
    const newScore = score + (correct ? 1 : 0);
    if (idx + 1 < QUIZ.length) { setScore(newScore); setIdx(idx + 1); setSelected(null); }
    else { setScore(newScore); setDone(true); onComplete?.(newScore); }
  };

  if (done) {
    const pct = Math.round((score / QUIZ.length) * 100);
    return (
      <div style={{ display: "grid", gap: 10 }}>
        <Card>
          <div style={{ fontWeight: 800 }}>{score}/{QUIZ.length}</div>
          <div style={{ color: "var(--text-muted)" }}>{pct}% correct</div>
        </Card>
        <div><button onClick={() => { setIdx(0); setSelected(null); setScore(0); setDone(false); }} style={{ padding: 10, borderRadius: 8, background: "var(--surface-alt)" }}>Retake</button></div>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}><div>Question {idx + 1}/{QUIZ.length}</div><div style={{ color: "var(--text-muted)" }}>{q.source}</div></div>
      <Card>
        <div style={{ fontWeight: 800 }}>{q.q}</div>
        <div style={{ marginTop: 10, display: "grid", gap: 8 }}>
          {q.options.map((o, i) => (
            <button key={i} onClick={() => setSelected(i)} style={{ padding: 12, borderRadius: 10, background: selected === i ? "#DDEFFB" : "#fff", border: "1px solid var(--border)", textAlign: "left" }}>{o}</button>
          ))}
        </div>
      </Card>
      <div><button onClick={submit} disabled={selected === null} style={{ padding: 12, borderRadius: 10, background: TILE_BLUE, color: "#fff", opacity: selected === null ? 0.5 : 1 }}>{idx + 1 < QUIZ.length ? "Next" : "Finish"}</button></div>
    </div>
  );
}

